/* User-provided transparent tool photographs; crop via viewBox, preserving proportions. */
(function(){var items={"trim": {"url":"data:image/webp;base64,", "box": [199.5, 35.5, 112.0, 440.0]}, "brush": {"url":"data:image/webp;base64,", "box": [239.0, 35.5, 34.0, 440.5]}, "carve": {"url":"data:image/webp;base64,", "box": [233.0, 36.0, 45.5, 440.0]}, "stamp": {"url":"data:image/webp;base64,", "box": [144.0, 38.0, 224.5, 435.0]}, "erase": {"url":"data:image/webp;base64,", "box": [120.0, 40.5, 271.5, 432.0]}, "glaze": {"url":"data:image/webp;base64,", "box": [181.0, 35.5, 148.5, 440.5]}, "glazeBrush": {"url":"data:image/webp;base64,", "box": [216.5, 36.5, 78.0, 439.5]}, "sponge": {"url":"data:image/webp;base64,", "box": [38, 38, 400, 333], "size": [476, 409]}};Object.keys(items).forEach(function(key){var im=items[key].image=new Image();im.src=items[key].url;});window.TodakToolImages={markup:function(key){var t=items[key];if(!t)return '';var b=t.box;return '<svg class="toolPhoto" viewBox="'+b.join(' ')+'" aria-hidden="true"><image href="'+t.url+'" width="'+(t.size?t.size[0]:512)+'" height="'+(t.size?t.size[1]:512)+'"/></svg>';},draw:function(c,key,x,y,height,angle){var t=items[key];if(!t||!t.image.complete||!t.image.naturalWidth)return false;var b=t.box,width=height*b[2]/b[3];c.save();c.translate(x,y);c.rotate(angle||0);c.drawImage(t.image,b[0],b[1],b[2],b[3],-width/2,-2,width,height);c.restore();return true;}};})();
